/** Ephemeral browser qualification input, generated by actual care commands. */
import {writeFileSync} from "node:fs";
import {maintainedLife,playerSimulation,benchmarkShapes,BENCHMARK_START} from "./daily-benchmark";
import {encodePet,PROTOTYPE_REVISION,LINEAGE_RECIPE_VERSION} from "../src/pet-format";
import {NEEDS_CATALOG_VERSION,NEEDS_RULES_VERSION} from "../src/needs";
const hour=Number(process.argv[3]??366*24);
if(![0,24,7*24,90*24,364*24,365*24,366*24].includes(hour))throw new RangeError("Unsupported qualification fixture age");
const game=maintainedLife("REAL-YEAR-SAVE",Math.ceil(hour/24)).get(hour)!;
const parts=benchmarkShapes.mosaic,simulation=playerSimulation(parts,game,true);
simulation.materialStateAt(hour/24);
const raw=encodePet({version:8,algorithmVersion:7,revision:PROTOTYPE_REVISION,
  mode:"infant",name:"A year of real care",seed:game.seed,parts,needTimeline:[],groomingTimeline:[],
  bornAt:BENCHMARK_START,age:0,catalogVersion:NEEDS_CATALOG_VERSION,needsRulesVersion:NEEDS_RULES_VERSION,
  life:{lineageVersion:LINEAGE_RECIPE_VERSION,anatomicalClock:"daily-365-v1",parts,mode:"infant",seed:game.seed,
    name:"A year of real care",game,groomingTimeline:[],anatomicalCheckpoint:simulation.exportAnatomicalCheckpoint()}});
writeFileSync(process.argv[2],raw);console.log(JSON.stringify({bytes:Buffer.byteLength(raw),commands:game.commandHistory.length,day:hour/24}));
